-- Madras Engineering College -- control plane (SuperCampusControl).
-- Roles, their grants, the people, and which roles each person holds.
-- Generated by seed/mec/generate_seed.py. Re-running is safe.
\set ON_ERROR_STOP on
BEGIN;

-- One bcrypt hash, reused for every account: this is a development dataset
-- with a single shared password, so per-account salts would buy nothing and
-- cost 245 rounds of key stretching.
CREATE TEMP TABLE mec_secret AS SELECT crypt('Mec@2026', gen_salt('bf', 12)) AS hash;

-- Roles ----------------------------------------------------------------------
INSERT INTO authz.roles (id, tenant_id, role_key, name, team, scope_description,
        portal_family, protected, active, created_by, updated_by)
VALUES ('18828d0e-42ed-5af2-80d2-7e6189bd80f8'::uuid, (SELECT id FROM platform.tenants WHERE slug = 'mec'), 'student', 'Student', 'Students', 'Sees their own academic record, orders, passes and fees', 'student', false, true, 'mec-seed', 'mec-seed')
ON CONFLICT (tenant_id, role_key) DO UPDATE SET
    name = EXCLUDED.name, team = EXCLUDED.team,
    scope_description = EXCLUDED.scope_description,
    portal_family = EXCLUDED.portal_family, active = true,
    updated_by = 'mec-seed', updated_at = now();

